linked.css:
body { margin: 12px; }
.linked-previews { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
easy-canvas { display: block; width: 100%; height: 340px; }

linked.code:
const shared = {};
// Pan and zoom are on by default. Uncomment to disable them:
// plot.setAttribute('controls', 'false');
// Hide helper axes with { axes: false }, or custom axes with:
// plot.setAttribute('default-axes-on', 'false');
const xs = Array.from({length: 121}, (_, i) => i / 10);
for (const [id, fn, title] of [
  ['gallery-linked-one', Math.sin, 'Sine'],
  ['gallery-linked-two', Math.cos, 'Cosine']
]) {
  const plot = document.getElementById(id);
  plot.linkInfo(['xmin', 'xmax'], shared);
  plot.drawingLoop = () => plot.hotAndReady.linePlot({
    xs, ys: xs.map(fn)
  }, {title, legendLabels: []});
}

themes.code:
const plots = ['theme-line', 'theme-bar', 'theme-donut'].map(id =>
  document.getElementById(id));
// Uncomment one of these lines to try a theme. Ctrl+/ toggles comments.
let theme = 'auto';
// theme = 'light';
// theme = 'dark';
// theme = 'paper';
// theme = 'forest';
// theme = 'midnight';
// theme = 'blueprint';
for (const plot of plots) plot.theme = theme;

const xs = Array.from({length: 61}, (_, i) => i / 10);
plots[0].drawingLoop = () => plots[0].hotAndReady.linePlot({
  xs, signal: xs.map(Math.sin), trend: xs.map(x => Math.cos(x) * 0.6)
}, {
  title: 'Line plot', inputs: ['xs', 'xs'], outputs: ['signal', 'trend'],
  legendLabels: ['Signal', 'Trend'], xLabel: 'Input', yLabel: 'Value',
});
plots[1].drawingLoop = () => plots[1].hotAndReady.barPlot({
  bars: ['A', 'B', 'C', 'D'], heights: [12, 19, 8, 15]
}, {
  title: 'Bar chart', xLabel: 'Category', yLabel: 'Count', legendLabels: []
});
plots[2].drawingLoop = () => plots[2].hotAndReady.donutChart({
  values: [45, 32, 23], labels: ['Product', 'Support', 'Research']
}, {title: 'Donut chart', showLabels: false});

// For your own control, setting plot.theme is the only step needed.
// Optional overrides:
// plots[0].themeColors = {background: '#102b26', fontFamily: 'Georgia, serif'};

themes.css:
body { margin: 12px; font-family: system-ui, sans-serif; }
.theme-previews { display: grid; grid-template-columns: repeat(3, minmax(240px, 1fr)); gap: 12px; overflow-x: auto; }
easy-canvas { display: block; width: 100%; height: 280px; }
